/* From Uiverse.io by Shoh2008 - Tags: loader */
.__UIV_SCOPE__ .loader {
  width: 84px;
  height: 84px;
  position: relative;
  overflow: hidden;
}

.__UIV_SCOPE__ .loader:before, .__UIV_SCOPE__ .loader:after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: yellow;
  transform: translate(-50% , 100%)  scale(0);
  animation: push_4051 2s infinite ease-in;
}

.__UIV_SCOPE__ .loader:after {
  animation-delay: 1s;
}

@keyframes push_4051 {
  0% {
    transform: translate(-50% , 100%)  scale(1);
  }

  15% , 25% {
    transform: translate(-50% , 50%)  scale(1);
  }

  50% , 75% {
    transform: translate(-50%, -30%) scale(0.5);
  }

  80%,  100% {
    transform: translate(-50%, -50%) scale(0);
  }
}
